const fs = require('fs');
const html = fs.readFileSync('landing/index.html', 'utf8');
const m = html.match(/<script type="module">([\s\S]*?)<\/script>/);
if (!m) { console.log('NO MODULE SCRIPT FOUND'); process.exit(1); }
fs.writeFileSync('check.mjs', m[1]);
// crude tag balance check for key elements
for (const tag of ['div','section','figure','main','header','footer','a','span','p','ul','li','h1','h2','canvas','script','style']) {
  const open = (html.match(new RegExp('<' + tag + '(\\s|>)', 'g')) || []).length;
  const close = (html.match(new RegExp('</' + tag + '>', 'g')) || []).length;
  const selfClosing = false;
  if (open !== close) console.log(`TAG MISMATCH: <${tag}> open=${open} close=${close}`);
}
console.log('TAG CHECK DONE');


