/* Progressive enhancement: a gentle three.js shimmer on the painted
   fields. The CSS reconstruction above is the source of truth; if the
   CDN or WebGL is unavailable, nothing changes for the visitor. */
try {
  const { default: THREE_NS } = await import('https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js')
    .then(m => ({ default: m }));
  const T = THREE_NS;
  const canvas = document.getElementById('gl');
  const frame = canvas.parentElement;
  if (!canvas || !frame) throw new Error('no canvas');

  const renderer = new T.WebGLRenderer({ canvas, alpha: true, antialias: true });
  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));

  const scene = new T.Scene();
  const camera = new T.OrthographicCamera(-1, 1, 1, -1, 0, 1);
  const geo = new T.PlaneGeometry(2, 2);

  // Overlay quads match the CSS fields' colours and geometry exactly.
  function quad(left, top, width, height, color){
    const m = new T.Mesh(geo, new T.MeshBasicMaterial({ color, transparent: true, opacity: 0 }));
    m.frustumCulled = false;
    m.userData = { left, top, width, height };
    scene.add(m);
    return m;
  }
  // Orthographic pixel space
  const meshes = [
    quad(0.37, 0.00, 0.63, 0.73, 0xd42a1e),  // red: top right
    quad(0.00, 0.85, 0.24, 0.15, 0x1b52a0),  // blue: bottom left
    quad(0.86, 0.85, 0.14, 0.15, 0xf2c500),  // yellow: bottom right
  ];
  let W = 1, H = 1;
  function resize(){
    W = frame.clientWidth; H = frame.clientHeight;
    renderer.setSize(W, H, false);
    camera.left = 0; camera.right = W; camera.top = 0; camera.bottom = H;
    camera.updateProjectionMatrix();
  }
  resize();
  addEventListener('resize', resize);

  const clock = new T.Clock();
  renderer.setAnimationLoop(() => {
    const t = clock.getElapsedTime();
    meshes.forEach((m, i) => {
      const u = m.userData;
      m.scale.set(u.width * W, u.height * H, 1);
      m.position.set((u.left + u.width / 2) * W, (u.top + u.height / 2) * H, 0);
      m.material.opacity = 0.10 + 0.07 * Math.sin(t * 0.8 + i * 2.1); // subtle breathing
    });
    renderer.render(scene, camera);
  });
} catch (e) {
  /* CSS-only fallback — intentional, silent. */
}


